import { useId, useState, type HTMLAttributes, type ReactNode } from 'react';
import '../theme.css';
import './accordion.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export interface AccordionItem {
  value: string;
  title: ReactNode;
  content: ReactNode;
  disabled?: boolean;
}

export interface AccordionProps extends HTMLAttributes<HTMLDivElement> {
  items: AccordionItem[];
  /** Lets several sections stay open. By default, opening one closes the others. */
  multiple?: boolean;
  /** The values open at first. */
  defaultOpen?: string[];
  /** Use a heading level that fits the page outline. */
  headingAs?: 'h2' | 'h3' | 'h4';
}

/** Sections that fold. The height animates in CSS, with no measuring. */
export function Accordion({ items, multiple = false, defaultOpen = [], headingAs: Heading = 'h3', className, ...rest }: AccordionProps) {
  const id = useId();
  const [open, setOpen] = useState<string[]>(defaultOpen);

  function toggle(value: string) {
    setOpen((current) => {
      if (current.includes(value)) return current.filter((item) => item !== value);
      return multiple ? [...current, value] : [value];
    });
  }

  return (
    <div {...rest} className={cx('ws-accordion', className)}>
      {items.map((item, index) => {
        const expanded = open.includes(item.value);
        // By position: a value may hold characters an id cannot.
        const triggerId = `${id}-${index}-trigger`;
        const panelId = `${id}-${index}-panel`;
        return (
          <div key={item.value} className="ws-accordion__item" data-open={expanded ? '' : undefined}>
            <Heading className="ws-accordion__heading">
              <button
                type="button"
                className="ws-accordion__trigger"
                id={triggerId}
                aria-expanded={expanded}
                aria-controls={panelId}
                disabled={item.disabled}
                onClick={() => toggle(item.value)}
              >
                <span>{item.title}</span>
                <svg className="ws-accordion__chevron" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                  <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </button>
            </Heading>
            {/* Inert while closed, so links inside it leave the tab order. */}
            <div className="ws-accordion__panel" id={panelId} role="region" aria-labelledby={triggerId} inert={!expanded}>
              <div className="ws-accordion__clip">
                <div className="ws-accordion__content">{item.content}</div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

.ws-accordion {
  box-sizing: border-box;
  min-width: 0;
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-md);
}

.ws-accordion__item + .ws-accordion__item {
  border-block-start: 1px solid var(--ws-color-divider);
}

.ws-accordion__heading {
  margin: 0;
  font: inherit;
}

.ws-accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ws-space-3);
  width: 100%;
  min-height: 44px;
  margin: 0;
  padding: 10px var(--ws-space-4);
  border: 0;
  background: transparent;
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-md);
  font-weight: var(--ws-weight-medium);
  line-height: var(--ws-leading-tight);
  text-align: start;
  cursor: pointer;
}

.ws-accordion__trigger:disabled {
  color: var(--ws-color-text-muted);
  cursor: not-allowed;
  opacity: 0.6;
}

.ws-accordion__trigger:focus-visible {
  border-radius: var(--ws-radius-md);
  outline: var(--ws-focus-width) solid var(--ws-color-focus);
  outline-offset: -2px;
}

.ws-accordion__chevron {
  flex: none;
  width: 16px;
  height: 16px;
  color: var(--ws-color-text-muted);
  transition: transform var(--ws-duration) var(--ws-ease);
}

.ws-accordion__item[data-open] .ws-accordion__chevron {
  transform: rotate(180deg);
}

/* A grid row can animate from 0fr to 1fr, which height: auto cannot. */
.ws-accordion__panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--ws-duration-slow) var(--ws-ease);
}

.ws-accordion__item[data-open] .ws-accordion__panel {
  grid-template-rows: 1fr;
}

.ws-accordion__clip {
  min-height: 0;
  overflow: hidden;
}

.ws-accordion__content {
  padding: 0 var(--ws-space-4) var(--ws-space-4);
  color: var(--ws-color-text-muted);
  line-height: var(--ws-leading);
}
